import type { Implementation } from '@/lib/types';

const LABEL: Record<string, string> = {
  c: 'C',
  cpp: 'C++',
  'x86-asm': 'x86 asm',
  unresolved: 'no definition found',
};

const TITLE: Record<string, string> = {
  c: 'Implemented in C in this repository.',
  cpp: 'Implemented in C++ in this repository.',
  'x86-asm':
    'Implemented in retained x86 assembly under src/asmsource/ — disassembled from the original game binary rather than rewritten in C.',
  unresolved:
    'Declared here, but the lexical index found no definition. It may be generated by a macro, defined in a vendored library, or genuinely missing.',
};

/** How a callable is actually implemented. Assembly is called out deliberately. */
export function ImplementationBadge({ value }: { value: Implementation | string }) {
  if (!value) return null;
  const tone = value === 'x86-asm' ? 'asm' : value === 'unresolved' ? 'warn' : 'accent';
  return (
    <span className={`badge ${tone}`} title={TITLE[value] ?? value}>
      {LABEL[value] ?? value}
    </span>
  );
}

export function KindBadge({ kind }: { kind: string }) {
  return <span className="badge">{kind}</span>;
}

export function AreaBadge({ area, codol }: { area: string; codol?: boolean }) {
  if (!area) return null;
  return <span className={codol ? 'badge accent' : 'badge'}>{area}</span>;
}

export function SourceLink({
  file,
  line,
  children,
}: {
  file: string;
  line?: number;
  children?: React.ReactNode;
}) {
  return (
    <span className="mono small faint" title={`${file}${line ? `:${line}` : ''}`}>
      {children ?? (
        <>
          {file}
          {line ? `:${line}` : ''}
        </>
      )}
    </span>
  );
}
